type Fixture=Awaited<ReturnType<typeof fixture>>;
async function background(f:Fixture,schedule=false){const errors:{code?:string;message?:string}[]=[],database:Database={async connect(){const c=f.pg.runtime?await f.pg.runtime.connect():{query:f.pg.query.bind(f.pg),release(){}};await c.query('SET ROLE kavosh_automation_worker');return {async query<Row>(sql:string,p?:unknown[]){try{return await c.query<Row>(sql,p);}catch(error){const e=error as {code?:string;message?:string};errors.push({code:e.code,message:e.message});throw error;}},release(destroy?:boolean){c.release(destroy);}};}};try{return {...await(schedule?processOneReportSchedule:processOneReport)(database,[f.a]),errors};}finally{if(!f.pg.runtime)await f.pg.exec('RESET ROLE');}}
