check('payroll liability remittances read protects its aggregate from a real concurrent hidden-bank record',async f=>{
 const h=await remittanceFixture(f);assert.equal((await f.request(h.remittancePath,h.remittanceInput)).response.status,201);const bank=await f.made('finance/accounts',{code:'REMIT-READ-HIDDEN',name:'Hidden concurrent funding',kind:'asset',operationalRole:'bank',hubId:f.otherHub,currencyId:f.currency.id,currencyVersion:1,reason:'Synthetic independent source'}),runtime=f.pg.runtime!,connect=runtime.connect.bind(runtime);let release!:()=>void,reached!:()=>void;const gate=new Promise<void>(r=>{release=r;}),atHistory=new Promise<void>(r=>{reached=r;});let held=false;runtime.connect=async()=>{const c=await connect(),query=c.query.bind(c);c.query=async<Row=Record<string,unknown>>(sql:string,args?:unknown[])=>{const result=await query<Row>(sql,args);if(!held&&sql.startsWith('SELECT NOT EXISTS(SELECT 1 FROM public.payrun_remittances pay')){held=true;reached();await gate;}return result;};return c;};let reader:ReturnType<typeof f.request>|undefined,writer:ReturnType<typeof f.request>|undefined;try{reader=f.request(h.remittanceStatus,undefined,'staff');await Promise.race([atHistory,reader.then(()=>{throw new Error('Read ended before history gate');})]);writer=f.request(h.remittancePath,{...h.remittanceInput,reference:'LATE-HIDDEN',fundingAccount:{id:bank.id,version:1}});let waiting=false;for(let k=0;k<100;k++){waiting=(await f.pg.query<{n:number}>("SELECT count(*)::integer n FROM pg_stat_activity WHERE datname=current_database() AND wait_event_type='Lock' AND wait_event='advisory'")).rows[0].n>0;if(waiting)break;await new Promise(r=>setTimeout(r,2));}assert.equal(waiting,true,'real writer must wait on the held worker gate');release();const [read,write]=await Promise.all([reader,writer]);assert.equal(read.response.status,200,JSON.stringify(read.body));assert.equal(read.body.data.paid,'100.00');assert.equal(write.response.status,201,JSON.stringify(write.body));assert.equal((await f.request(h.remittanceStatus,undefined,'staff')).response.status,404);assert.equal((await f.request(h.remittanceStatus)).body.data.paid,'200.00');}finally{release();await Promise.allSettled([reader,writer].filter(Boolean));runtime.connect=connect;}
},true);
