check('mixed-hub hourly payruns consume each conserved allocation once and block whole-source correction until all groups release',async f=>{
 const timeRole=await f.made('roles',{name:'Cross-hub actual time',permissions:[{capability:'session-time.record',effect:'allow'}]});await f.pg.query('INSERT INTO public.role_assignments(academy_id,id,person_id,role_id,all_hubs) VALUES($1,$2,$3,$4,true)',[f.a,randomUUID(),f.actors.staff.person,timeRole.id]);const first=(await f.request('classes/'+f.c.id+'/sessions')).body.data[0];assert.equal((await f.request('sessions/'+first.id+'/change',{expectedVersion:1,reason:'Synthetic past class',change:{kind:'reschedule',start:'2026-01-05T10:00',end:'2026-01-05T11:00'}})).response.status,200);
 const c=await f.made('classes',{hubId:f.otherHub,courseId:f.c.course_id,courseVersion:1,name:'Second actual class',mode:'in_person',schedule:{oneOff:[{start:'2026-01-05T10:30',end:'2026-01-05T11:30'}]}}),a=await f.made('classes/'+c.id+'/staff',{personId:f.actors.staff.person,role:'teacher',startsOn:'2026-01-01',reason:'Synthetic second class'}),second=(await f.request('classes/'+c.id+'/sessions')).body.data[0],e=await f.create({code:'SECOND-HOURLY',hubId:f.otherHub,definition:{...f.definition,region:'Quebec'},components:[{...f.hourly,amount:'30',method:null,assignment:{id:a.id,version:1}}]});assert.equal(e.response.status,201);
 for(const[s,assignment,version,startsAt,endsAt]of [[first,f.assignment,2,'2026-01-05T15:00:00Z','2026-01-05T16:00:00Z'],[second,a,1,'2026-01-05T15:30:00Z','2026-01-05T16:30:00Z']] as const)assert.equal((await f.request('sessions/'+s.id+'/my-time',{expectedVersion:0,assignmentId:assignment.id,assignmentVersion:1,sessionVersion:version,startsAt,endsAt,reason:'PRIVATE recorded time'},'staff')).response.status,201);
 const accounts=[];for(const[kind,operationalRole]of [['expense','expense'],['liability','payable']])accounts.push(await f.made('finance/accounts',{code:'HOURLY-'+kind.toUpperCase(),name:'Synthetic academy mapping',kind,operationalRole,hubId:null,currencyId:f.currency.id,currencyVersion:1,reason:'Synthetic hourly mapping'}));const h=await f.request('payroll/hourly-accruals',{...f.base,personId:f.input.personId,from:'2026-01-05',through:'2026-01-05',timeZone:'UTC',currencyId:f.currency.id,basis:'actual',reference:'MIXED-HOURS',expenseAccount:{id:accounts[0].id,version:1},liabilityAccount:{id:accounts[1].id,version:1},earningReview:'PRIVATE actual earning',roundingReview:'PRIVATE retain overlap allocation'});assert.equal(h.response.status,201,JSON.stringify(h.body));assert.equal(h.body.data.grossBaseAmount,'40.00');
 const left={kind:'hourly',sourceId:h.body.data.id,allocationId:f.engagement.id},right={...left,allocationId:e.body.data.id};assert.equal((await f.group({earnings:[left,right]})).body.error.code,'PAYRUN_SEPARATE_LEGAL_CONTEXT_REQUIRED');const l=await made(f,{earnings:[left]}),r=await made(f,{reference:'SECOND-HOURLY-RUN',earnings:[right]});assert.equal(l.grossAmount,'10.00');assert.equal(r.grossAmount,'30.00');assert.equal((await f.request('payroll/payruns/'+l.id,undefined,'manager')).response.status,200);assert.equal((await f.request('payroll/payruns/'+r.id,undefined,'manager')).response.status,404);
 const readiness=await f.request('payroll/payruns/'+l.id+'/readiness');assert.equal(readiness.response.status,200,JSON.stringify(readiness.body));assert.equal(readiness.body.data.sessionCount,2);assert.equal(readiness.body.data.classInputReviewCurrent,false);assert.equal((await f.request('payroll/payruns/'+l.id+'/readiness',undefined,'manager')).response.status,404);
 const correct=()=>f.request('payroll/hourly-accruals/'+h.body.data.id+'/void',{period:f.base.period,postedOn:'2026-02-01',reason:'PRIVATE retained correction'});assert.equal((await f.cancel(l.id)).response.status,201);assert.equal((await correct()).body.error.code,'PAYRUN_CANCEL_BEFORE_SOURCE_CORRECTION');assert.equal((await f.cancel(r.id)).response.status,201);assert.equal((await correct()).response.status,201);
});
check('payrun native cancellation requires its exact retained header effect and every claim release',async f=>{
 const d=await made(f),r=await f.cancel(d.id,'staff');assert.equal(r.response.status,202);const p=(await f.pg.query<any>('SELECT * FROM public.approval_requests WHERE id=$1',[r.body.approval.id])).rows[0];
 await native(f,async()=>{await f.pg.query('INSERT INTO public.payrun_group_cancellations(academy_id,id,run_id,input,source_snapshot,approval_id,created_by) VALUES($1,$2,$3,$4::jsonb,$5::jsonb,$6,$7)',[f.a,p.target_id,d.id,JSON.stringify(p.payload),JSON.stringify(p.review_context),p.id,f.actors.master.person]);await f.pg.query("UPDATE public.approval_requests SET status='applied',version=2,reviewer_id=$2,decided_at=now() WHERE id=$1",[p.id,f.actors.master.person]);await assert.rejects(f.pg.exec('COMMIT'),/PAYRUN_CANCEL_EFFECT_REQUIRED/);});
 await native(f,async()=>{await f.pg.query('INSERT INTO public.payrun_group_cancellations(academy_id,id,run_id,input,source_snapshot,approval_id,created_by) VALUES($1,$2,$3,$4::jsonb,$5::jsonb,$6,$7)',[f.a,p.target_id,d.id,JSON.stringify(p.payload),JSON.stringify(p.review_context),p.id,f.actors.master.person]);await f.pg.query('UPDATE public.payrun_groups SET cancellation_id=$2 WHERE id=$1',[d.id,p.target_id]);await f.pg.query("UPDATE public.approval_requests SET status='applied',version=2,reviewer_id=$2,decided_at=now() WHERE id=$1",[p.id,f.actors.master.person]);await assert.rejects(f.pg.exec('COMMIT'),/PAYRUN_EXACT_CLAIMS_REQUIRED/);});assert.equal((await f.approve(p.id)).response.status,200);
});
check('one tiny payrun-versus-source-correction race cannot retain a voided earning or deadlock',async f=>{
 const a=await Promise.all([f.group({earnings:[f.refs[0]]}),f.request('payroll/project-accruals/'+f.refs[0].sourceId+'/void',{period:f.base.period,postedOn:'2026-02-01',reason:'PRIVATE concurrent correction'})]);assert.deepEqual(a.map(v=>v.response.status).sort(),[201,409]);const groups=(await f.pg.query<any>('SELECT cancellation_id FROM public.payrun_groups')).rows,source=(await f.pg.query<any>('SELECT void_id FROM public.payroll_project_accruals WHERE id=$1',[f.refs[0].sourceId])).rows[0];assert.equal(groups.length,source.void_id?0:1);
},true);
check('late source mutation rolls back payrun claims and native legal snapshots before a safe identical retry',async f=>{
 await f.pg.exec(`CREATE FUNCTION public.late_payrun_source() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog AS $$BEGIN UPDATE public.work_engagement_revisions SET definition=jsonb_set(definition,'{region}','"CHANGED"'::jsonb) WHERE academy_id=NEW.academy_id AND engagement_id=NEW.allocation_id;RETURN NEW;END$$;CREATE TRIGGER late_payrun_source AFTER INSERT ON public.payrun_earning_claims FOR EACH ROW EXECUTE FUNCTION public.late_payrun_source()`);const key=randomUUID();assert.equal((await f.group({},'master',key)).response.status,400);assert.equal((await f.pg.query('SELECT * FROM public.payrun_groups')).rows.length,0);assert.equal((await f.pg.query('SELECT * FROM public.payrun_earning_claims')).rows.length,0);assert.equal((await f.pg.query<any>("SELECT definition->>'region' r FROM public.work_engagement_revisions WHERE engagement_id=$1",[f.engagement.id])).rows[0].r,'Ontario');await f.pg.exec('DROP TRIGGER late_payrun_source ON public.payrun_earning_claims');assert.equal((await f.group({},'master',key)).response.status,201);
});
check('payrun totals normalize retained currency precision exactly instead of converting or rounding earlier sources',async f=>{
 assert.equal((await f.request('finance/currencies/'+f.currency.id+'/change',{expectedVersion:1,unitScale:3,reason:'Synthetic explicit precision revision'})).response.status,200);assert.equal((await f.amend(f.engagement.id,{currency:{id:f.currency.id,version:2},components:[{...f.project,amount:'125.005'}]})).response.status,200);
 const accounts=[];for(const[kind,operationalRole]of [['expense','expense'],['liability','payable']])accounts.push(await f.made('finance/accounts',{code:'PRECISE-'+kind.toUpperCase(),name:'Synthetic precision mapping',kind,operationalRole,hubId:f.hub,currencyId:f.currency.id,currencyVersion:2,reason:'Synthetic precision mapping'}));const p=await f.request('payroll/project-accruals',{...f.projectBody,engagement:{id:f.engagement.id,version:2},termsVersion:2,units:1,deliveryRef:'PRECISE',expenseAccount:{id:accounts[0].id,version:1},liabilityAccount:{id:accounts[1].id,version:1}});assert.equal(p.response.status,201,JSON.stringify(p.body));const d=await made(f,{earnings:[...f.refs,{kind:'project',sourceId:p.body.data.id,allocationId:f.engagement.id}]});assert.equal(d.grossAmount,'3475.255');assert.equal(d.unitScale,3);assert.equal(d.earnings.find((v:any)=>v.sourceId===f.refs[0].sourceId).grossAmount,'250.00');
});
check('grouping preserves exact large aggregate money without exchange or repricing old terms',async f=>{
 const amount='999999999999999999999999999999999999.99';assert.equal((await f.amend(f.engagement.id,{components:[{...f.project,amount}]})).response.status,200);const refs=[];for(const ref of ['LARGE-1','LARGE-2']){const p=await f.request('payroll/project-accruals',{...f.projectBody,engagement:{id:f.engagement.id,version:2},termsVersion:2,deliveryRef:ref,units:1});assert.equal(p.response.status,201);refs.push({kind:'project',sourceId:p.body.data.id,allocationId:f.engagement.id});}const d=await made(f,{earnings:refs});assert.equal(d.grossAmount,'1999999999999999999999999999999999999.98');
 assert.equal((await f.amend(f.engagement.id,{expectedVersion:2,effectiveOn:'2027-01-01',definition:{...f.definition,region:'Quebec'},components:[f.project]})).response.status,200);assert.equal((await f.request('payroll/payruns/'+d.id)).body.data.grossAmount,d.grossAmount);assert.equal((await f.cancel(d.id)).response.status,201);
});
test('actual107to108 preserves recorded project salary and bonus and starts with no run or claims',async()=>{
 const f=await fixture({throughSchema:107});try{const snapshot=async()=>{const out:Record<string,unknown>={};for(const t of ['finance_journals','finance_journal_lines','payroll_project_accruals','payroll_salary_accruals','payroll_adjustments','work_engagement_revisions'])out[t]=(await f.pg.query('SELECT to_jsonb(x) x FROM public.'+t+' x ORDER BY to_jsonb(x)::text')).rows;return out;};const before=await snapshot();await f.pg.exec(await readFile(new URL('../db/migrations/108_payrun_groups.sql',import.meta.url),'utf8'));assert.deepEqual(await snapshot(),before);assert.equal((await f.pg.query('SELECT public.schema_revision() n')).rows[0].n,108);assert.equal((await f.pg.query('SELECT * FROM public.payrun_groups')).rows.length,0);assert.equal((await made(f)).grossAmount,'3350.25');}finally{await f.pg.close();}
});
